-- sdg_targets (8)
insert into public.sdg_targets (id, text) values
  ('4.1', 'Every girl and boy completes free, equitable, quality primary and secondary school.'),
  ('4.3', 'Equal access to affordable technical, vocational and university education.'),
  ('4.4', 'More youth and adults with skills for jobs and decent work, including technical and digital skills.'),
  ('4.5', 'Equal access to education for everyone, including people with disabilities, Indigenous peoples and children in vulnerable situations; no gender gaps.'),
  ('4.6', 'All youth reach literacy and numeracy.'),
  ('4.7', 'Learners gain knowledge for sustainable development, human rights, gender equality, peace, global citizenship and respect for cultural diversity.'),
  ('4.a', 'Safe, inclusive learning environments that work for students with disabilities and for all genders.'),
  ('4.c', 'More qualified teachers, including through teacher training.')
