-- tools (19)
insert into public.tools (id, name, company, category_id, ease, verified, subjects, description, uses, personas, free_status, pricing, privacy, connects, equity, review_note, urls, not_offered) values
  ('magicschool', 'MagicSchool', 'MagicSchool AI', 'plan', 1, true, array['all']::text[], 'An all-in-one teacher toolkit with 80+ tools for lesson plans, rubrics, leveled texts and family emails, plus student tools your class can use with guardrails.', array['Lesson plans', 'Rubrics', 'IEP drafts', 'Leveled texts', 'Family emails', 'Student tools']::text[], '[{"id":"teacher","top":true,"why":"Covers most weekly planning tasks in one place, and it''s free for teachers."},{"id":"sped","why":"Has an IEP generator and accommodation tools for first drafts."},{"id":"coach","why":"Easy first tool for AI PD; districts get dashboards and admin controls.","top":true}]'::jsonb, 'yes', 'Free plan for teachers. MagicSchool Plus: $8.33/user/month billed annually, or $12.99/month billed monthly. School and district plans: custom pricing.', '{"ferpa":true,"ferpaNote":"MagicSchool states FERPA compliance and is in the iKeepSafe FERPA certification program.","coppa":true,"coppaNote":"MagicSchool states COPPA compliance and is in the iKeepSafe COPPA Safe Harbor program.","dpa":"yes","dpaNote":"Custom DPAs are offered on Enterprise (school/district) plans.","students":true,"studentsNote":"Has student-facing tools that teachers launch and monitor.","dataNote":"MagicSchool has a SOC 2 Type II audit, 1EdTech TrustEd Apps certification and a Common Sense privacy rating. It says student data is never used to train AI models. It also lists GDPR and New York Ed Law 2-d.","location":{"hq":{"t":"U.S. (Boulder, Colorado)"},"stored":{"t":"U.S."},"processed":{"t":"U.S. All listed service providers, including its AI providers, are in the U.S. Its privacy policy also says data may go to other countries, without naming them.","check":true}}}'::jsonb, '{"roster":[{"n":"Clever","v":true},{"n":"ClassLink","v":true}],"lms":[{"n":"Google Classroom","v":true},{"n":"Canvas","v":true},{"n":"Schoology","v":true,"via":"through Edlink"}],"grades":[],"paid":"Clever, ClassLink, Canvas and Schoology need the Enterprise (district) plan; Google Classroom works on every plan.","note":"It can pull student writing in from Canvas or Schoology, but it can''t send feedback or grades back."}'::jsonb, '{"free":{"s":"warn","t":"Free for teachers; the student tools are listed under paid plans."},"device":{"s":"unknown","t":"Device needs aren''t published on the pages we checked."},"lang":{"s":"ok","t":"Interface in 24 languages; translates into 98."},"access":{"s":"ok","t":"Claims WCAG 2.2 AA with published accessibility reports; tested with screen readers."}}'::jsonb, null, array['https://www.magicschool.ai/pricing', 'https://www.magicschool.ai/privacy', 'https://www.magicschool.ai/faq', 'https://www.magicschool.ai/accessibility', 'https://www.magicschool.ai/integrations', 'https://www.magicschool.ai/privacy/trust', 'https://trust.magicschool.ai/subprocessors']::text[], '{}'::text[]),
  ('brisk', 'Brisk Teaching', 'Brisk', 'plan', 1, true, array['all']::text[], 'A Chrome and Edge extension that works right inside Google Docs, Slides and YouTube: give feedback, change reading levels, or turn a video into a quiz without leaving the page.', array['Feedback on student writing', 'Change reading level', 'Quizzes from videos', 'Works in Google Docs']::text[], '[{"id":"teacher","why":"Works inside Docs and Slides you already use, so there''s nothing new to learn."},{"id":"sped","why":"One click changes a text''s reading level or translates it."},{"id":"coach","why":"Fast win in Google districts; low setup."}]'::jsonb, 'yes', 'Free for teachers. Premium (schools and districts) and Intelligence (districts, built around your curriculum): custom pricing, charged per student.', '{"ferpa":true,"ferpaNote":"Brisk states FERPA compliance.","coppa":true,"dpa":"yes","dpaNote":"Brisk says it has signed the National DPA (SDPC) in about two dozen states and will sign district DPAs.","students":true,"studentsNote":"Brisk Boost gives students guided AI activities a teacher sets up.","dataNote":"Brisk''s privacy center says it is SOC 2 Type II compliant, but its plans page says it is still working toward SOC 2 Type II. It says student and teacher inputs are never used to train AI.","coppaNote":"Brisk states COPPA compliance.","location":{"hq":{"t":"U.S. (California)"},"stored":{"t":"U.S. and other countries, not named.","check":true},"processed":{"t":"U.S. Other countries: not stated by the company. Its list of service providers gives no locations.","check":true}}}'::jsonb, '{"roster":[{"n":"ClassLink","v":true}],"lms":[{"n":"Google Classroom","v":true},{"n":"Canvas","v":true,"via":"LTI 1.3"},{"n":"Schoology","v":true,"via":"LTI 1.3"},{"n":"Blackboard","v":true}],"grades":[],"paid":"Canvas, Schoology and Blackboard need the Schools & Districts plan.","note":"It works with Google Assignments in Canvas, Schoology, Blackboard and Google Classroom. It doesn''t send grades back."}'::jsonb, '{"free":{"s":"warn","t":"Free for teachers; the student tool''s premium features need a school plan."},"device":{"s":"warn","t":"Full tools need the Chrome or Edge extension on a computer. Phones and tablets can create and share in the browser."},"lang":{"s":"ok","t":"50+ languages."},"access":{"s":"ok","t":"Commits to WCAG 2.2 AA. A VPAT covering teacher and student tools is available on request."}}'::jsonb, 'Brisk''s privacy center says SOC 2 Type II compliant, but its plans page says it''s still working toward it. Brisk also names 24 states with a signed National DPA, but says 25. Ask Brisk about both.', array['https://www.briskteaching.com/plans', 'https://www.briskteaching.com/privacy/privacy-center', 'https://www.briskteaching.com/how-brisk-integrates', 'https://help.briskteaching.com/hc/en-us/articles/53379861693332', 'https://www.briskteaching.com/privacy/data-subprocessors']::text[], array['Sending grades back to your LMS']::text[]),
  ('khanmigo', 'Khanmigo for Teachers', 'Khan Academy', 'plan', 1, true, array['math', 'sci', 'ela', 'ss']::text[], 'Khan Academy''s AI teaching assistant for planning lessons, writing questions and building rubrics, from a nonprofit known for math and science practice.', array['Lesson hooks', 'Math practice', 'Question sets', 'Rubrics']::text[], '[{"id":"teacher","why":"Strong for math and science, and free for teachers."},{"id":"sped","why":"Step-by-step math explanations help with reteaching."}]'::jsonb, 'yes', 'Free for teachers (18+) in nearly every country. Learners and parents: $4/month or $44/year (U.S. only). Districts: request pricing.', '{"ferpa":true,"ferpaNote":"Khan Academy says its district plans comply with FERPA. Student accounts in a district partnership are school accounts covered by FERPA.","coppa":true,"dpa":"district","dpaNote":"Students get Khanmigo only through a district rollout, which comes with a district agreement.","students":false,"studentsNote":"The free teacher version is for adults only; teachers can''t give students access.","coppaNote":"Khan Academy says its district plans comply with COPPA.","dataNote":"Khan Academy doesn''t let AI companies train on student data, and doesn''t share student names with them. It has yearly SOC 2 Type 2 audits and has signed the Student Privacy Pledge.","location":{"hq":{"t":"U.S. (Mountain View, California; nonprofit)"},"stored":{"t":"U.S."},"processed":{"t":"U.S. Where its AI provider processes data: not stated by the company."}}}'::jsonb, '{"roster":[{"n":"Clever","v":true,"via":"Districts Enterprise plan"},{"n":"ClassLink","v":true,"via":"Districts Enterprise plan"}],"lms":[{"n":"School LMS","v":true,"via":"Clever Instant Login"}],"grades":[],"paid":"Automatic rostering needs the Khan Academy Districts Enterprise plan (more than 1,000 students).","note":"It shares progress and completion data, not grades."}'::jsonb, '{"free":{"s":"warn","t":"Free for teachers only; students need a paid district rollout."},"device":{"s":"ok","t":"Works in any web browser, including phones. The Khan Academy app doesn''t have the teacher tools."},"lang":{"s":"warn","t":"43 languages. Only English, Hindi, Spanish and Portuguese are fully tested."},"access":{"s":"ok","t":"Khan Academy has a VPAT for WCAG 2.1 AA for its district plans."}}'::jsonb, null, array['https://www.khanmigo.ai/pricing', 'https://support.khanacademy.org/hc/en-us/sections/17101838561165-Rostering-Guidelines', 'https://support.khanacademy.org/hc/en-us/articles/36808726375693', 'https://support.khanacademy.org/hc/en-us/articles/4406593496077', 'https://www.khanacademy.org/about/privacy-policy']::text[], array['Student use in the free teacher version (adults only)', 'Sending grades (it shares progress, not grades)']::text[]),
  ('diffit', 'Diffit', 'Diffit', 'plan', 1, true, array['ela', 'ss', 'sci', 'wl']::text[], 'Type a topic or paste a text, pick a [[lexile|reading level]], and Diffit builds a leveled reading with vocabulary, questions and graphic organizers.', array['Leveled readings', 'Vocabulary lists', 'Question sets', 'Translations']::text[], '[{"id":"sped","top":true,"why":"Fastest way to get the same content at a reading level every student can access."},{"id":"teacher","why":"Great for ELA, social studies and science readings."},{"id":"coach","why":"Quick demo of differentiation for PD."}]'::jsonb, 'yes', 'Always free for teachers (the free plan keeps the last 90 days of resources). Individual premium: $14.99 billed monthly or $149.99 billed annually. Diffit for Schools: a flat yearly price based on enrollment. Districts: custom quote.', '{"ferpa":true,"ferpaNote":"Diffit states FERPA compliance.","coppa":true,"dpa":"yes","dpaNote":"Diffit says it has signed the National DPA and SDPC statewide agreements.","students":false,"studentsNote":"Teachers make materials; students get the finished handouts.","dataNote":"Diffit says it collects no student data and uses no personal data to train AI. It collects only teacher names, emails and IP addresses.","coppaNote":"Diffit states COPPA compliance.","location":{"hq":{"t":"U.S."},"stored":{"t":"U.S."},"processed":{"t":"U.S."}}}'::jsonb, '{"roster":[],"lms":[],"grades":[],"note":"Can be added as an app tile in Clever or ClassLink, but there''s no class sync yet (Diffit says it''s planned). The free plan downloads PDFs. The school plan exports to Google (including Classroom), Microsoft and Canva."}'::jsonb, '{"free":{"s":"ok","t":"Always free for teachers, and students get the finished handouts, so there''s no student cost."},"device":{"s":"ok","t":"Works on any device with a current web browser (Chrome, Edge, Firefox or Safari)."},"lang":{"s":"ok","t":"70+ languages."},"access":{"s":"ok","t":"Diffit says it meets WCAG 2.1 AA. A VPAT is available on request."}}'::jsonb, null, array['https://web.diffit.me/pricing', 'https://web.diffit.me/privacy', 'https://support.diffit.me/hc/en-us/articles/39956259851149-Adding-Diffit-to-your-ClassLink-and-Clever-App', 'https://support.diffit.me/hc/en-us/articles/37675797544717', 'https://support.diffit.me/hc/en-us/articles/25391565692941', 'https://web.diffit.me/individual-teacher-subscription', 'https://web.diffit.me/privacy-policy']::text[], array['Class roster sync (Diffit says it''s planned)', 'Student logins or student AI']::text[]),
  ('schoolai', 'SchoolAI', 'SchoolAI', 'student', 2, true, array['all']::text[], 'Teachers create guided AI "Spaces" for students, then watch a live dashboard showing who''s stuck, who''s done, and who may need a check-in.', array['Guided student AI', 'Live class dashboard', 'Tutoring', 'Check-ins']::text[], '[{"id":"teacher","why":"Lets students use AI inside guardrails you set, while you watch progress live."},{"id":"counselor","why":"Says it flags possible crisis language and connects students to trusted adults."},{"id":"coach","why":"A district option for safe student-facing AI."}]'::jsonb, 'limited', 'Free trial with 5 Space launches a year. Pro and Scale plans through sales; no prices published.', '{"ferpa":true,"ferpaNote":"SchoolAI states FERPA compliance.","coppa":true,"dpa":"yes","dpaNote":"The free trial includes a standard DPA through the terms of service. Pro adds a standard district-wide DPA. Scale allows custom changes.","students":true,"studentsNote":"Built for students to use AI in teacher-made Spaces.","dataNote":"SchoolAI has SOC 2 Type 2 and says it doesn''t train AI on student data.","coppaNote":"SchoolAI states COPPA compliance and is COPPA Safe Harbor certified.","location":{"hq":{"t":"U.S. (Lehi, Utah)"},"stored":{"t":"U.S."},"processed":{"t":"U.S. All listed service providers, including its AI providers, are in the U.S. Its website privacy notice also says data may go to other countries, without naming them.","check":true}}}'::jsonb, '{"roster":[{"n":"Infinite Campus","v":true},{"n":"PowerSchool","v":true},{"n":"Skyward","v":true},{"n":"Aeries","v":true},{"n":"Synergy","v":true},{"n":"Clever","v":true},{"n":"ClassLink","v":true}],"lms":[{"n":"Canvas","v":true},{"n":"Google Classroom","v":true},{"n":"Schoology","v":true}],"grades":[],"paid":"SIS rostering and full LMS connections need the Pro plan.","note":"SchoolAI lists 30+ SIS partners but doesn''t say whether it connects directly or through a rostering service."}'::jsonb, '{"free":{"s":"warn","t":"Free trial only (5 launches a year). Student portals need the top Scale plan."},"device":{"s":"unknown","t":"The browser extension works only in Chrome-based browsers like Chrome and Edge, not Safari or Firefox. Device needs for Spaces aren''t published."},"lang":{"s":"ok","t":"Live translation in 60+ languages; speech-to-text in about 100."},"access":{"s":"ok","t":"WCAG 2.1 AA with a published conformance report; screen reader compatible."}}'::jsonb, null, array['https://schoolai.com/pricing', 'https://schoolai.com/trust', 'https://schoolai.com/accessibility', 'https://schoolai.com/integrations', 'https://trust.schoolai.com/subprocessors']::text[], '{}'::text[]),
  ('curipod', 'Curipod', 'Curipod', 'student', 1, true, array['all']::text[], 'Teacher-led reading and writing lessons that work alongside your curriculum. Students write in class, get AI feedback right away, and revise in the same period. They join with a code, no accounts.', array['Writing practice', 'Instant AI feedback', 'Reading & discussion', 'Test prep']::text[], '[{"id":"teacher","why":"Whole-class writing practice with instant AI feedback, so students revise while you''re there."},{"id":"coach","why":"Students join without accounts and there''s no student chatbot, which makes approval easier."}]'::jsonb, 'yes', 'Free for every teacher. School and district plans: custom pricing.', '{"ferpa":true,"ferpaNote":"Curipod states FERPA compliance.","coppa":true,"dpa":"yes","dpaNote":"Curipod has signed state DPAs in 23 states. In other states, the district sends its own DPA. DPAs come with paid plans.","students":true,"studentsNote":"Students join with a code, no accounts, and Curipod says there are no AI chatbots for students.","coppaNote":"Curipod states COPPA compliance.","dataNote":"Curipod says teacher and student data is never used to train AI. It also lists SOPPA (an Illinois student privacy law) and GDPR (Europe''s privacy law) compliance.","location":{"hq":{"t":"Not stated by the company. The site footer names Curipod AS, a Norwegian company type.","check":true},"stored":{"t":"U.S. for teacher and student data (EU storage on request)."},"processed":{"t":"U.S. Beyond that: not stated by the company. For teachers (not students), it may use email addresses for ads on Meta, Google and TikTok.","check":true}}}'::jsonb, '{"roster":[{"n":"Clever","v":true,"via":"sign-in"},{"n":"ClassLink","v":true,"via":"sign-in"},{"n":"Google","v":true,"via":"sign-in"}],"lms":[],"grades":[],"paid":"Clever, ClassLink and Google sign-in need a district plan.","note":"Students join with a code, so there''s no class list to sync."}'::jsonb, '{"free":{"s":"ok","t":"Students join free without accounts; the free plan has a weekly session limit."},"device":{"s":"unknown","t":"Device needs aren''t stated; a paper backup is only on the paid school plan."},"lang":{"s":"ok","t":"Lessons can be translated into any language, per Curipod. Translation is limited on the free plan."},"access":{"s":"ok","t":"Curipod''s own accessibility report (June 2025) says it meets WCAG 2.2 AA, except keyboard use of the drawing tool."}}'::jsonb, null, array['https://curipod.com/', 'https://curipod.com/pricing', 'https://curipod.com/privacy-policy', 'https://curipod.com/c/state-and-district-privacy-agreements']::text[], array['Student accounts (students join with a code)', 'AI chatbots for students']::text[]),
  ('gemini', 'Gemini for Education', 'Google', 'general', 1, true, array['all']::text[], 'Google''s [[genai|generative AI]] assistant, included in Google Workspace for Education. It writes, summarizes and translates, and works inside Gmail, Docs and Classroom with your district''s protections.', array['Family emails', 'Translation', 'Summaries', 'Works in Gmail & Docs']::text[], '[{"id":"counselor","top":true,"why":"Already in your district Google account, with protections for school data."},{"id":"office","top":true,"why":"Drafts and translates notices right in Gmail and Docs."},{"id":"teacher","why":"Good general helper inside the Google tools you already use."},{"id":"admin","why":"Summaries and drafts across Workspace."}]'::jsonb, 'yes', 'Included at no charge in all Google Workspace for Education editions (through your district account). Google AI Pro for Education add-on: $15/user/month with a one-year commitment, or $24 month-to-month.', '{"ferpa":true,"ferpaNote":"Google says Gemini for Education supports FERPA compliance.","coppa":true,"dpa":"district","dpaNote":"Covered by your district''s Google Workspace for Education agreement.","students":true,"studentsNote":"Admins can turn it on or off by group; stricter rules apply for students under 18.","coppaNote":"Google says Gemini for Education supports COPPA compliance.","dataNote":"Google says your data isn''t reviewed by people, used to train AI models or used for ads.","location":{"hq":{"t":"U.S. (Mountain View, California)"},"stored":{"t":"Not stated by the company. On Education Standard and Plus, admins can choose to keep stored Gemini data in the U.S. or Europe.","check":true},"processed":{"t":"Any country where Google or its service providers have facilities."}}}'::jsonb, '{"roster":[{"n":"OneRoster","v":true,"via":"through Google Classroom"}],"lms":[{"n":"Google Classroom","v":true},{"n":"Canvas","v":true,"via":"Gemini LTI"},{"n":"Schoology","v":true,"via":"Gemini LTI"},{"n":"Moodle","v":true,"via":"Gemini LTI"}],"grades":[{"n":"Infinite Campus","v":true,"via":"Google Classroom grade export"},{"n":"PowerSchool","v":true,"via":"Google Classroom grade export"},{"n":"Skyward","v":true,"via":"Google Classroom grade export"},{"n":"Aspen","v":true,"via":"Google Classroom grade export"}],"paid":"Sending grades to an SIS needs Google''s Education Plus or Teaching & Learning Upgrade license.","note":"The grade connection is a Google Classroom feature, not part of Gemini itself."}'::jsonb, '{"free":{"s":"ok","t":"Included free for students of all ages in Workspace for Education; admins choose who gets it."},"device":{"s":"ok","t":"Web, Android and iOS."},"lang":{"s":"ok","t":"More than 40 languages."},"access":{"s":"warn","t":"Google published an accessibility report for the Gemini web app (Dec 2025). Many items only partly meet WCAG 2.2 AA."}}'::jsonb, null, array['https://edu.google.com/workspace-for-education/editions/compare-editions/', 'https://edu.google.com/intl/ALL_us/ai/gemini-for-education/', 'https://www.google.com/accessibility/static/pdf/google-gemini-web-vpat.pdf', 'https://support.google.com/edu/classroom/answer/16538778', 'https://knowledge.workspace.google.com/admin/compliance/data-covered-by-data-regions']::text[], '{}'::text[]),
  ('notebooklm', 'Gemini Notebook (NotebookLM)', 'Google', 'general', 2, true, array['all']::text[], 'Upload your own documents, like a handbook, curriculum guide or grant, and ask questions that it [[grounding|answers only from those sources]], with citations. Google renamed it Gemini Notebook; many people still call it NotebookLM.', array['Answers from your documents', 'Policy Q&A', 'Study guides', 'Audio overviews']::text[], '[{"id":"coach","top":true,"why":"Answers questions straight from your district policy and curriculum, with citations."},{"id":"admin","why":"Turns long grants and handbooks into briefs you can trust."},{"id":"teacher","why":"Builds study guides from your own unit materials."}]'::jsonb, 'yes', 'Free in all Google Workspace for Education editions, with daily limits (for example 50 chats and 3 audio overviews a day). AI Pro for Education raises the limits.', '{"ferpa":true,"ferpaNote":"Google says Gemini Notebook (NotebookLM) is a Workspace for Education core service that supports FERPA compliance.","coppa":true,"dpa":"district","dpaNote":"Covered by your district''s Google Workspace for Education agreement.","students":true,"studentsNote":"Available to students if the district turns it on; under-18 rules apply.","coppaNote":"Google says Gemini Notebook (NotebookLM) is a Workspace for Education core service that supports COPPA compliance.","dataNote":"Google says your files and chats aren''t reviewed by people, used to train AI models or used for ads.","location":{"hq":{"t":"U.S. (Mountain View, California)"},"stored":{"t":"Not stated by the company. Google''s data-location settings don''t apply to it.","check":true},"processed":{"t":"Any country where Google or its service providers have facilities."}}}'::jsonb, '{"roster":[],"lms":[{"n":"Google Classroom","v":true},{"n":"Canvas","v":true,"via":"Gemini LTI"},{"n":"Schoology","v":true,"via":"Gemini LTI"},{"n":"Moodle","v":true,"via":"Gemini LTI"}],"grades":[],"note":"Teachers can attach notebooks to Classroom posts and see students'' chats in notebooks they assign. No grade connection."}'::jsonb, '{"free":{"s":"ok","t":"Included in Workspace for Education for all ages when the admin turns it on. Students under 18 get extra guardrails."},"device":{"s":"ok","t":"Web, Android and iOS."},"lang":{"s":"ok","t":"Interface in 50+ languages. Sources and audio overviews in 80+."},"access":{"s":"warn","t":"Google published an accessibility report (Dec 2025). Some parts, like mind maps, only partly meet WCAG 2.2 AA."}}'::jsonb, null, array['https://edu.google.com/intl/ALL_us/ai-notebooklm/', 'https://support.google.com/notebooklm/answer/16337734', 'https://services.google.com/fh/files/misc/google_notebooklm_vpat.pdf', 'https://knowledge.workspace.google.com/admin/compliance/data-covered-by-data-regions']::text[], '{}'::text[]),
  ('copilot', 'Microsoft Copilot', 'Microsoft', 'general', 1, true, array['all']::text[], 'Microsoft''s AI assistant for schools on Microsoft 365. Copilot Chat drafts, summarizes and translates; the full version works inside Word, Outlook, Excel and Teams, and its Teach feature helps with lesson plans and rubrics.', array['Staff emails', 'Agendas', 'Schedules in Excel', 'Summaries', 'Lesson plans (Teach)']::text[], '[{"id":"admin","top":true,"why":"Works inside Outlook, Word, Excel and Teams, where admin work already happens."},{"id":"office","why":"Quick drafts and translations with your school login."},{"id":"teacher","why":"The Teach feature helps with lessons and rubrics in Microsoft schools."},{"id":"counselor","why":"Protected chat with your school account."}]'::jsonb, 'yes', 'Copilot Chat is included with Microsoft 365 education licenses (A1, A3 and A5 today). Microsoft Copilot academic add-on: $18/user/month (priced as of October 2025). Microsoft says the free Office 365 A1 plan retires January 1, 2028.', '{"ferpa":false,"ferpaNote":"FERPA wasn''t named on the Microsoft pages we checked. Ask Microsoft or your district.","coppa":null,"dpa":"district","dpaNote":"Covered by your district''s Microsoft 365 agreement. Web searches Copilot sends to Bing fall under separate Microsoft terms.","students":true,"studentsNote":"Blocked under 13. For students 13–17, it stays off until district IT sets their age group.","dataNote":"Microsoft says data stays in your school''s account and is never used to train its foundation models.","location":{"hq":{"t":"U.S. (Redmond, Washington)"},"stored":{"t":"Your school''s home country (the U.S. for U.S. schools)."},"processed":{"t":"The U.S., the EU or other regions, when AI data centers are busy."}}}'::jsonb, '{"roster":[{"n":"Infinite Campus","v":true,"via":"School Data Sync"},{"n":"Skyward","v":true,"via":"School Data Sync"},{"n":"Aeries","v":true,"via":"School Data Sync"},{"n":"Synergy","v":true,"via":"School Data Sync"},{"n":"ClassLink","v":true,"via":"School Data Sync"}],"lms":[{"n":"Microsoft Teams","v":true}],"grades":[{"n":"Canvas","v":true,"via":"Microsoft 365 LTI"},{"n":"Schoology","v":true,"via":"Microsoft 365 LTI"},{"n":"Blackboard","v":true,"via":"Microsoft 365 LTI"},{"n":"Brightspace","v":true,"via":"Microsoft 365 LTI"},{"n":"Moodle","v":true,"via":"Microsoft 365 LTI"}],"paid":"Microsoft''s School Data Sync is free with Microsoft 365 education licenses.","note":"PowerSchool isn''t on Microsoft''s School Data Sync list. A Teams-to-Infinite Campus gradebook sync is reported but not confirmed."}'::jsonb, '{"free":{"s":"ok","t":"No extra cost with Microsoft 365 A1, A3 or A5 licenses; for students 13–17, IT must turn it on."},"device":{"s":"ok","t":"Web, desktop and mobile apps, plus inside Outlook, Teams and Edge."},"lang":{"s":"ok","t":"48 languages for school accounts."},"access":{"s":"warn","t":"Microsoft tests its products against WCAG, but we found no Copilot-specific report."}}'::jsonb, null, array['https://www.microsoft.com/en-us/education/products/copilot-in-education', 'https://learn.microsoft.com/en-us/copilot/plan/privacy-and-protections', 'https://learn.microsoft.com/en-us/copilot/microsoft-365/microsoft-365-copilot-privacy']::text[], array['Access for students under 13']::text[]),
  ('chatgpt', 'ChatGPT for Teachers', 'OpenAI', 'general', 1, true, array['all']::text[], 'A version of ChatGPT for K–12 educators with teacher-focused features. ChatGPT Edu is the separate version districts and universities buy for staff.', array['Planning', 'Writing help', 'Custom GPTs', 'Brainstorming']::text[], '[{"id":"teacher","why":"Flexible for any subject once you have a good prompt."},{"id":"admin","why":"Drafting and analysis for big writing tasks."},{"id":"counselor","why":"Helps draft resources and plain-language messages."}]'::jsonb, 'yes', 'Free for verified U.S. K–12 educators (teachers, staff, school leaders and district admins) through June 2028. OpenAI may change the price after that, with advance notice. Not for students. ChatGPT Edu: district contract, price not published.', '{"ferpa":true,"ferpaNote":"OpenAI says it is built to help schools meet FERPA requirements.","coppa":null,"dpa":"yes","dpaNote":"OpenAI''s own student data privacy agreement, accepted when the workspace is created. Check whether your district needs its own.","students":false,"studentsNote":"Teacher version is for educators, not students.","dataNote":"OpenAI says chats aren''t used to train its models by default. Authorized OpenAI staff and contractors may review some chats for support, abuse or legal reasons.","location":{"hq":{"t":"U.S. (San Francisco, California)"},"stored":{"t":"Not stated by the company.","check":true},"processed":{"t":"Not stated for this plan. OpenAI''s list for its school and business plans includes many countries, including the United Arab Emirates, India, Singapore, Japan and EU countries.","check":true}}}'::jsonb, '{"roster":[],"lms":[],"grades":[],"note":"Works with Canva and with files from Google Drive and Microsoft 365. Admins get single sign-on (SAML) and account syncing (SCIM). No SIS or LMS connection."}'::jsonb, '{"free":{"s":"ok","t":"Free for verified U.S. K–12 staff through June 2028. Not for students."},"device":{"s":"ok","t":"Web, plus iPhone, Android and desktop apps (from OpenAI''s general ChatGPT download page)."},"lang":{"s":"unknown","t":"About 59 interface languages reported; not confirmed."},"access":{"s":"unknown","t":"No accessibility statement found."}}'::jsonb, null, array['https://help.openai.com/en/articles/12844995-chatgpt-for-teachers', 'https://openai.com/index/chatgpt-for-teachers/', 'https://chatgpt.com/plans/k12-teachers/', 'https://openai.com/policies/sub-processor-list/']::text[], array['Use by students (educators only)', 'LMS or student information system (SIS) connections']::text[]),
  ('canva', 'Canva for Education', 'Canva', 'create', 1, true, array['all']::text[], 'Design tool for flyers, slides, newsletters and posters, with Magic Studio AI to draft text, resize designs and translate.', array['Flyers & posters', 'Newsletters', 'Slides', 'Translate designs', 'Pro design apps (Affinity)']::text[], '[{"id":"office","why":"Polished flyers and newsletters fast, with built-in translation."},{"id":"teacher","why":"Class slides, posters and student design projects."},{"id":"counselor","why":"Eye-catching college and career handouts."}]'::jsonb, 'yes', 'Free for eligible K–12 teachers and students. Whole schools and districts can get it free on request.', '{"ferpa":true,"ferpaNote":"FERPA certified by iKeepSafe.","coppa":true,"dpa":"yes","dpaNote":"Canva has signed the National Data Privacy Agreement and several state addenda. Districts can sign on to an existing agreement.","students":true,"studentsNote":"Students join only when a teacher invites them to a class.","coppaNote":"COPPA certified by iKeepSafe. For students under 13, the school or teacher must get parental consent.","dataNote":"Canva says it doesn''t use students'' Canva Education content to improve its AI. It lists ISO 27001, SOC 2, SOC 3 and PCI DSS certifications.","location":{"hq":{"t":"Australia (Sydney)"},"stored":{"t":"U.S."},"processed":{"t":"Australia, New Zealand, the Philippines, the UK, Singapore, Europe and the U.S., plus service providers around the world."}}}'::jsonb, '{"roster":[],"lms":[{"n":"Google Classroom","v":true},{"n":"Canvas","v":true},{"n":"Schoology","v":true,"via":"LTI"},{"n":"Microsoft Teams","v":true}],"grades":[],"note":"Teachers and students can sign up with Clever, Google or Microsoft. Canva also lists D2L Brightspace, Moodle and Blackboard."}'::jsonb, '{"free":{"s":"ok","t":"Free for K–12 teachers and students; schools and districts free on request."},"device":{"s":"ok","t":"Works in Chrome, Edge, Safari and Firefox, including on Chromebooks. Apps for iPhone, iPad and Android. iPads need iOS 15.4 or newer."},"lang":{"s":"ok","t":"Translate turns designs into 100+ languages. AI usage limits apply."},"access":{"s":"ok","t":"Canva says its core product supports WCAG 2.1 AA, documented in its VPAT."}}'::jsonb, null, array['https://www.canva.com/education/', 'https://www.canva.com/trust/education/', 'https://www.canva.com/help/about-canva-for-education/', 'https://www.canva.com/accessibility/', 'https://www.canva.com/help/technical-requirements/', 'https://www.canva.com/help/translate-canva-designs/', 'https://www.canva.com/trust/privacy/', 'https://www.canva.com/security/', 'https://www.canva.com/policies/privacy-policy/']::text[], '{}'::text[]),
  ('eduaide', 'Eduaide.Ai', 'Eduaide', 'plan', 2, true, array['all']::text[], 'A teacher planning assistant with many resource types, such as graphic organizers, question sets and games, plus feedback and rubric helpers.', array['Graphic organizers', 'Rubrics', 'Question sets', 'Feedback']::text[], '[{"id":"teacher","why":"Lots of resource formats beyond worksheets."},{"id":"sped","why":"Graphic organizers and scaffolds on demand."}]'::jsonb, 'limited', 'Free plan: 24 credits a month (up to 8 resources). Pro: $49.99/year or $5.99/month. School plans: custom.', '{"ferpa":true,"ferpaNote":"Eduaide says it is FERPA-compliant. We found no outside certification.","coppa":true,"dpa":"none","dpaNote":"Eduaide hasn''t published a data privacy agreement. Ask about one through school licensing.","students":false,"studentsNote":"For adults only: Eduaide says it is not for people under 18.","dataNote":"Eduaide says it doesn''t collect student data and deletes student information if it''s entered. Its AI providers (OpenAI and Anthropic) can''t train on what you enter.","coppaNote":"Eduaide says it is COPPA-compliant.","location":{"hq":{"t":"U.S. (San Francisco, California)"},"stored":{"t":"U.S."},"processed":{"t":"U.S."}}}'::jsonb, '{"roster":[],"lms":[],"grades":[],"note":"Google sign-in, plus export to Google Docs, Google Forms, Word or PDF. No SIS or LMS connection found."}'::jsonb, '{"free":{"s":"warn","t":"Free plan with monthly limits, and adults only, so no student access."},"device":{"s":"unknown","t":"A web app in your browser. Eduaide doesn''t list device needs."},"lang":{"s":"warn","t":"Translates into 29+ languages, on the Pro plan only."},"access":{"s":"unknown","t":"No accessibility statement found."}}'::jsonb, null, array['https://www.eduaide.ai/pricing', 'https://www.eduaide.ai/privacy', 'https://www.eduaide.ai/privacy-center', 'https://www.eduaide.ai/compare/best-ai-tools-for-teachers']::text[], array['A published data privacy agreement', 'Use by students (adults 18+ only)', 'LMS or class roster connections']::text[]),
  ('readwrite', 'Read&Write', 'Everway (formerly Texthelp)', 'student', 1, true, array['all']::text[], 'A reading and writing toolbar that reads text aloud, predicts words, translates, and uses AI to simplify hard text. Built for students with dyslexia, ADHD and other learning needs, and for multilingual learners.', array['Text-to-speech', 'Co:Writer word prediction', 'Simplify / Rewordify (AI)', 'Translation', 'Talk&Type speech-to-text', 'Screen masking']::text[], '[{"id":"sped","top":true,"why":"Made for reading and writing accommodations: read-aloud, word prediction and AI text simplifying."},{"id":"teacher","why":"Free for K–12 teachers; helps struggling readers and multilingual learners in any subject."},{"id":"coach","why":"Districts get deployment tools, usage reports and a testing mode that limits features."}]'::jsonb, 'limited', 'Free premium access for K–12 teachers. Student seats are billed yearly: district plans from $2.75 per seat (minimum purchase required), school group plans $18.30 per seat (150-seat minimum), or $184 a year for one person.', '{"ferpa":true,"ferpaNote":"Everway lists FERPA compliance.","coppa":true,"coppaNote":"Everway lists COPPA compliance.","dpa":"none","dpaNote":"Everway hasn''t published a National Data Privacy Agreement. Ask whether your district has an agreement.","students":true,"studentsNote":"Made for students; teachers and districts set it up.","dataNote":"Everway also lists SOPPA (an Illinois student privacy law), U.S. state privacy laws, GDPR (Europe''s privacy law), ISO/IEC 27001:2022 security certification and a 2026 ISAE 3000 privacy audit.","location":{"hq":{"t":"UK (Northern Ireland), with a U.S. office in New York"},"stored":{"t":"Not stated by the company overall. Different services store data in the U.S. or the EU.","check":true},"processed":{"t":"The U.S. and the EU (Amazon, Microsoft and Google cloud services)."}}}'::jsonb, '{"roster":[],"lms":[{"n":"Canvas","v":true},{"n":"Schoology","v":true},{"n":"Brightspace","v":true}],"grades":[],"note":"Works inside Google Docs, Microsoft Word, PDFs and web pages. No Clever or ClassLink rostering found."}'::jsonb, '{"free":{"s":"warn","t":"Free for teachers. Student seats are paid (district plans from $2.75 each per year, with a minimum purchase)."},"device":{"s":"ok","t":"Windows, Mac, Chromebook, iPad, iPhone and Android, in Chrome and Edge. Read-aloud works offline on Windows and Mac."},"lang":{"s":"warn","t":"Translates and works in several languages; Everway doesn''t publish a count."},"access":{"s":"warn","t":"Itself an assistive tool. Everway''s Trust Center lists accessibility reports for Windows, Mac, Chrome and iOS; we haven''t checked which WCAG level they cover."}}'::jsonb, null, array['https://www.everway.com/products/read-and-write-education/', 'https://www.everway.com/products/read-and-write-education/pricing/', 'https://trust.everway.com', 'https://trust.everway.com/subprocessors']::text[], array['A published National Data Privacy Agreement']::text[]),
  ('talkingpoints', 'TalkingPoints', 'TalkingPoints (nonprofit)', 'family', 1, true, array['all']::text[], 'Two-way messaging with families in 150+ languages, using AI translation backed by human translators. Families get regular texts, so they need no app, email or Wi-Fi.', array['Family messages', 'Translation', 'Two-way texting', 'Message Mentor (AI)', 'Attendance outreach']::text[], '[{"id":"office","top":true,"why":"Reach every family by text in their own language, with no app needed."},{"id":"teacher","why":"Free for individual teachers; families reply in their language and you read it in yours."},{"id":"counselor","why":"Two-way conversations with families in their own language, by text.","top":true},{"id":"admin","why":"School and district plans add rostering and reports."}]'::jsonb, 'limited', 'Free for individual teachers and always free for families. School and district plans: priced by quote.', '{"ferpa":true,"ferpaNote":"TalkingPoints says it is \"fully compliant with FERPA.\"","coppa":null,"coppaNote":"TalkingPoints says COPPA doesn''t apply because children under 13 don''t use it.","dpa":"none","dpaNote":"TalkingPoints uses its own standard contract terms and hasn''t published a National Data Privacy Agreement. Check with your district.","students":true,"studentsNote":"Mainly for staff and families. Districts can turn on Student Messaging for students 13 and older.","dataNote":"TalkingPoints says it never sells or rents personal information. It also lists MFIPPA (an Ontario, Canada privacy law).","location":{"hq":{"t":"U.S. (San Francisco, California; nonprofit)"},"stored":{"t":"U.S."},"processed":{"t":"U.S. All listed service providers are in the U.S."}}}'::jsonb, '{"roster":[{"n":"Clever","v":true},{"n":"ClassLink","v":true},{"n":"OneRoster","v":true}],"lms":[],"grades":[],"note":"TalkingPoints also mentions \"other SISs\" without naming them. Families can use texts, the web, or iOS and Android apps."}'::jsonb, '{"free":{"s":"ok","t":"Always free for families and free for individual teachers; run by a nonprofit."},"device":{"s":"ok","t":"Families need only a phone that gets texts. Apps for iOS and Android, plus the web."},"lang":{"s":"ok","t":"150+ languages, with AI translation backed by human translators and a K–12 glossary."},"access":{"s":"warn","t":"Has a short accessibility statement promising access for people with disabilities. No WCAG level or report published."}}'::jsonb, null, array['https://talkingpts.org/', 'https://talkingpts.org/faq/', 'https://talkingpts.org/privacy-and-security/', 'https://intercom.help/talkingpoints/en/articles/10073735-enable-student-messaging', 'https://talkingpts.org/subprocessors']::text[], array['A published National Data Privacy Agreement']::text[]),
  ('parentsquare', 'ParentSquare', 'ParentSquare', 'family', 2, true, array['all']::text[], 'District-wide family communication: alerts, two-way messages, forms and permission slips in 190+ languages. ParentSquare Intelligence adds AI tools and insights.', array['Alerts & notices', 'Two-way messages', 'Forms & permission slips', 'Translation', 'AI insights']::text[], '[{"id":"admin","top":true,"why":"One district system for alerts, messages and forms, with a signed National Data Privacy Agreement."},{"id":"office","why":"Send notices and forms families can read in their language, with no app or login needed."},{"id":"teacher","why":"Classroom messages and permission slips, if your district uses it."}]'::jsonb, 'no', 'District or school purchase only: Engage, Engage Premium and Engage 360 packages. A yearly fee based on enrollment; prices from sales.', '{"ferpa":true,"ferpaNote":"FERPA certified by iKeepSafe.","coppa":true,"coppaNote":"COPPA certified by iKeepSafe.","dpa":"yes","dpaNote":"Signatory of the Student Data Privacy Consortium''s National Data Privacy Agreement.","students":true,"studentsNote":"StudentSquare lets schools message middle and high school students (grades 6–12).","dataNote":"ParentSquare says it does not use school or family data to train AI models, and its AI features are opt-in. It has signed the Student Privacy Pledge. It lists SOC 2 Type II and iKeepSafe California student privacy certifications.","location":{"hq":{"t":"U.S. (Goleta, California)"},"stored":{"t":"Not stated by the company. Hosted on Amazon Web Services and Google Cloud.","check":true},"processed":{"t":"Not stated by the company. Its list of service providers gives no locations.","check":true}}}'::jsonb, '{"roster":[{"n":"PowerSchool","v":true,"via":"API, SSO or file transfer"},{"n":"Skyward","v":true,"via":"API, SSO or file transfer"},{"n":"Aeries","v":true,"via":"API, SSO or file transfer"},{"n":"Synergy","v":true,"via":"API or file transfer"},{"n":"Aspen","v":true,"via":"file transfer"},{"n":"Clever","v":true},{"n":"ClassLink","v":true}],"lms":[],"grades":[],"note":"Syncs families and classes from your SIS. Also lists Mindex SchoolTool and Aequitas. Single sign-on is supported."}'::jsonb, '{"free":{"s":"warn","t":"Free for families, but schools or districts must buy it."},"device":{"s":"ok","t":"Families get texts or use the app; no login or app required."},"lang":{"s":"ok","t":"Translates into 190+ languages."},"access":{"s":"ok","t":"Says its platform meets WCAG 2.1 and 2.2 AA, checked with automated and manual testing. No VPAT on its pages."}}'::jsonb, null, array['https://www.parentsquare.com/', 'https://www.parentsquare.com/pricing/', 'https://www.parentsquare.com/privacy/data-privacy-agreements/', 'https://www.parentsquare.com/designed-for-k12/integrations/', 'https://www.parentsquare.com/company/accessibility/', 'https://www.parentsquare.com/company/ai-principles/', 'https://www.parentsquare.com/company/ai-info-page/', 'https://www.parentsquare.com/resources/faqs/', 'https://trust.parentsquare.com/subprocessors']::text[], array['A free plan (district or school purchase only)']::text[]),
  ('goalbook', 'Goalbook Toolkit', 'Goalbook (Enome, Inc.)', 'plan', 2, true, array['all']::text[], 'Helps special educators write stronger IEPs: present levels, measurable standards-aligned goals, and specially designed instruction with progress-monitoring tools. Its AI feature, Threads, checks that the IEP fits together and suggests improvements.', array['IEP goals', 'Present levels', 'Specially designed instruction', 'Progress monitoring', 'IEP review (AI)', 'Goal translation to Spanish (AI)']::text[], '[{"id":"sped","top":true,"why":"Write clear, measurable IEP goals and matching instruction, with AI checks across the whole IEP."},{"id":"admin","why":"District plans with onboarding, PD and program analytics; Threads can be turned off to match your AI policy."},{"id":"teacher","why":"Research-based strategies for supporting students with IEPs in your class."}]'::jsonb, 'no', 'School membership starts at $5,150 a year. District membership: priced by quote. A trial sign-up is offered; its length isn''t stated.', '{"ferpa":true,"ferpaNote":"Goalbook says it is built to meet FERPA for special education records. Its policy says the district is responsible for FERPA consents.","coppa":true,"coppaNote":"Goalbook says it complies with COPPA. Its policy says it doesn''t knowingly collect personal information from children under 13.","dpa":"none","dpaNote":"Goalbook hasn''t published a standard or National Data Privacy Agreement. Its terms include a California student-data addendum. Check with your district.","students":false,"studentsNote":"For educators only. The terms exclude students, parents and the public, and users must be 13 or older.","dataNote":"Audited for SOC 2 Type I and Type II. Data is encrypted in transit and at rest. AI services see entered data only to answer a request, and it is never used to train models. Goalbook doesn''t keep district data after the contract ends. No ads.","location":{"hq":{"t":"U.S. (California)"},"stored":{"t":"U.S."},"processed":{"t":"U.S."}}}'::jsonb, '{"roster":[],"lms":[],"grades":[],"note":"Goalbook says it supports single sign-on (SSO) for district logins, but doesn''t name Clever, ClassLink or Google. No IEP-system connection is listed; you copy goals into your IEP system."}'::jsonb, '{"free":{"s":"warn","t":"Paid school or district membership, with a trial."},"device":{"s":"unknown","t":"Web-based. No device or browser requirements published."},"lang":{"s":"warn","t":"One-click AI translation of IEP goals into Spanish, plus Spanish progress-monitoring assessments. No other languages yet."},"access":{"s":"warn","t":"Aims for WCAG 2.1 AA \"to the greatest extent possible,\" with a yearly third-party audit. No VPAT published."}}'::jsonb, 'Goalbook doesn''t say whether Threads costs extra, which AI model it uses, or whether it drafts IEP text or only suggests changes.', array['https://goalbook.com/', 'https://goalbook.com/explore-toolkit/', 'https://goalbook.com/leadership/iep-development-and-educator-effectiveness-goalbook-threads/', 'https://goalbook.com/ai-goal-translation/', 'https://goalbook.com/privacy-center/', 'https://goalbook.com/privacy/toolkit/', 'https://goalbook.com/terms/', 'https://goalbook.com/accessibility/']::text[], array['Student accounts', 'Ads']::text[]),
  ('amira', 'Amira Learning', 'Amira Learning Inc.', 'student', 2, true, array['ela']::text[], 'An AI reading assistant that listens as students read aloud. It screens for reading risk (including dyslexia signs), tutors one-on-one, and gives teachers lesson plans, in English and Spanish.', array['Reading screener', 'Read-aloud tutoring (AI)', 'Dyslexia risk signs', 'Lesson plans from data', 'Spanish literacy', 'Teacher resource builder']::text[], '[{"id":"teacher","top":true,"why":"Every K–8 reader gets one-on-one read-aloud practice, and you get lesson plans from the results."},{"id":"sped","why":"Flags early signs of reading risk, including dyslexia, to guide support."},{"id":"admin","why":"State-approved screener in many states, with district reports and settings for how long audio is kept."}]'::jsonb, 'no', 'Bought by schools and districts; priced by quote. Not sold to families. No price or free plan published.', '{"ferpa":true,"ferpaNote":"Amira says it works under district or state contracts governed by FERPA, as a provider the district designates.","coppa":true,"coppaNote":"Amira says only school officials create student accounts, and schools consent for parents under COPPA''s school exception. Its Trust Center lists COPPA compliance.","dpa":"yes","dpaNote":"Amira says it supports district-specific data privacy agreements and has committed by contract to 2,000+ agencies not to sell student data.","students":true,"studentsNote":"Students in grades K–8 read aloud to Amira. Only educators create accounts, and there''s no public sign-up.","dataNote":"By default, practice audio isn''t saved and test audio is deleted within 48 hours of scoring; districts can pick other retention settings. No voiceprints. Recordings aren''t used directly to train AI; only de-identified data is. SOC 2 audited and 1EdTech TrustEd Apps certified. Doesn''t sell student data. Amira says it is not generative AI.","location":{"hq":{"t":"U.S. (San Francisco, California)"},"stored":{"t":"U.S. student audio is stored in Ohio. Other data: region not stated."},"processed":{"t":"Not stated by the company.","check":true}}}'::jsonb, '{"roster":[{"n":"Clever","v":true},{"n":"ClassLink","v":true},{"n":"OneRoster","v":true}],"lms":[{"n":"Google Classroom","v":true,"via":"sign-on"},{"n":"Schoology","v":true,"via":"sign-on"}],"grades":[],"note":"Also supports SAML sign-on, LTI and CSV/SFTP rostering. No grade sync is listed."}'::jsonb, '{"free":{"s":"warn","t":"District purchase only. No free plan for teachers or families."},"device":{"s":"ok","t":"Works on Chromebooks, iPads (Safari), Windows and Mac with 4 GB memory. Plan about 10 Mbps per device. Headsets are optional; a boom microphone is recommended."},"lang":{"s":"ok","t":"Fully bilingual in English and Spanish, including the Spanish suite Amira Lectura."},"access":{"s":"warn","t":"Built toward WCAG 2.1 AA and Section 508 (a goal, not a claim). No VPAT published."}}'::jsonb, 'Amira''s pages disagree on how districts opt out of model training: its Trust Center calls it a separate setting, while its privacy policy says short or no audio retention stops training.', array['https://amiralearning.com/', 'https://www.amiralearning.com/district-leaders', 'https://amiralearning.com/privacy-and-security', 'https://amiralearning.com/amira-privacy.html', 'https://amiralearning.com/amira-trust-center.html', 'https://amiralearning.com/accessibility-statement.html', 'https://www.amiralearning.com/state/amira-for-california']::text[], array['Family purchase', 'Voiceprints or voice IDs', 'Public student sign-up']::text[]),
  ('observation-copilot', 'Edthena Observation Copilot', 'Edthena (R3 Collaboratives, Inc.)', 'plan', 1, true, array['all']::text[], 'Turns a principal''s walkthrough or observation notes into a first draft of feedback that follows your teaching framework: evidence, strengths, areas to grow and next steps. You review and edit it before sharing.', array['Observation feedback', 'Walkthrough notes', 'Rubric alignment', 'Audio transcription', 'Teacher growth over time']::text[], '[{"id":"admin","top":true,"why":"Turns walkthrough notes into feedback that matches your framework, in much less time."},{"id":"coach","why":"Drafts evidence-based next steps tied to Danielson, Marzano, T-TESS or your district''s own rubric.","top":true}]'::jsonb, 'limited', 'Free for individual principals and school leaders, with unlimited teachers and observations. No credit card needed. District plans add a dashboard of trends across schools and start at about $1,000 per school per year.', '{"ferpa":true,"ferpaNote":"Edthena says Observation Copilot meets FERPA''s requirements and acts as a \"school official\" under FERPA.","coppa":true,"coppaNote":"Edthena says it is COPPA compliant.","dpa":"review","dpaNote":"Edthena says it can provide data-sharing agreements on request. None is published for Observation Copilot. Check with your district.","students":false,"studentsNote":"For principals, school leaders and authorized district staff only. Students do not use it.","dataNote":"Notes are encrypted. Edthena says it never sells student data, except as part of a company sale. Its privacy policy says Observation Copilot data is used to train Edthena''s own models; outside AI vendors (such as Google, Anthropic or OpenAI) may not train on it. It says it follows SOC 2 and ISO 27001 standards but names no certification. It has signed the Student Privacy Pledge.","location":{"hq":{"t":"U.S. (San Francisco, California)"},"stored":{"t":"Its pages disagree: one says the U.S., another says the U.S. or any other country.","check":true},"processed":{"t":"The U.S. or any other country where it or its providers have facilities."}}}'::jsonb, '{"roster":[],"lms":[],"grades":[],"note":"Edthena mentions single sign-on but names no provider. You can add notes, lesson plans, audio recordings and your own rubric. No school-system connections are listed. Edthena''s video-coaching platform is a separate product."}'::jsonb, '{"free":{"s":"ok","t":"Free for individual principals, with no limit on teachers or observations."},"device":{"s":"unknown","t":"Runs on the web. No device requirements are published."},"lang":{"s":"unknown","t":"No language information is published."},"access":{"s":"unknown","t":"No accessibility statement or VPAT was found."}}'::jsonb, 'Edthena''s pages disagree on whether data stays in the United States.', array['https://observationcopilot.com/', 'https://observationcopilot.com/pricing', 'https://observationcopilot.com/faq', 'https://observationcopilot.com/security', 'https://observationcopilot.com/blog/is-observation-copilot-ferpa-compliant', 'https://www.edthena.com/privacy-security/', 'https://www.edthena.com/privacy']::text[], array['Student accounts']::text[]),
  ('claude-for-teachers', 'Claude for Teachers', 'Anthropic', 'general', 2, true, array['all']::text[], 'A version of the Claude AI assistant for U.S. K–12 staff, with teaching skills, academic standards for all 50 states and partner tools for lesson plans, differentiation and family newsletters. For staff only, not students.', array['Lesson planning', 'Differentiation', 'Quizzes & checks for understanding', 'Family newsletters', 'Handouts & slides']::text[], '[{"id":"teacher","top":true,"why":"Plans lessons that match your state standards and differentiates materials, free for a year."},{"id":"coach","why":"Instructional coaches qualify, and the teaching skills are built on learning science."},{"id":"sped","why":"Helps adapt materials to different readiness levels. Use only student information your district has approved."},{"id":"counselor","why":"Counselors are eligible certificated staff."},{"id":"admin","why":"A free district account adds single sign-on, roles, usage tracking and one set of K–12 terms for all staff."}]'::jsonb, 'limited', 'Free for verified U.S. K–12 educators, and free for schools and districts on a district account. Sign up by June 30, 2027 to get one full year free; Anthropic hasn''t said what happens after that year. Usage limits apply; extra usage is billed only if a district admin turns it on.', '{"ferpa":true,"ferpaNote":"Anthropic''s K–12 terms say it acts as a \"school official\" under FERPA and the school controls student data. Use identifiable student information only if your district allows it.","coppa":null,"coppaNote":"Anthropic doesn''t mention COPPA. It says students don''t use Claude for Teachers.","dpa":"yes","dpaNote":"Anthropic publishes a U.S. K–12 Data Processing Agreement (Aug 28, 2026), with a Public Sector Addendum for public schools. Districts accept it once for all staff; individual teachers accept the K–12 terms themselves.","students":false,"studentsNote":"\"Claude for Teachers is not for students.\" There are no student accounts.","dataNote":"Anthropic says it won''t train its models on your chats or files, sell student data, or use it for ads. It must report a breach within 48 hours and deletes data within 30 days after an account ends. Anthropic lists SOC 2 Type II, ISO 27001 and ISO 42001 certifications.","location":{"hq":{"t":"U.S. (San Francisco, California)"},"stored":{"t":"U.S."},"processed":{"t":"The U.S., Europe, Asia or Australia. U.S.-only processing is offered only on usage-based Enterprise plans."}}}'::jsonb, '{"roster":[{"n":"SCIM provisioning","v":true,"via":"district accounts"}],"lms":[],"grades":[],"note":"District accounts use single sign-on with automatic account creation (SCIM or just-in-time). Partner tools include Learning Commons, ASSISTments, Brisk Teaching, Canva Education, Coteach, Diffit, Eedi, MagicSchool, Snorkl and TeachFX. On district accounts, admins choose which are on; none are on by default."}'::jsonb, '{"free":{"s":"ok","t":"Free for one year for verified U.S. K–12 staff and districts who sign up by June 30, 2027. Pricing after that isn''t stated."},"device":{"s":"warn","t":"Web, Mac, Windows, iPhone, iPad (iPadOS 18 or later) and Android (8.0 or later), plus a Chrome extension. Chromebooks aren''t named."},"lang":{"s":"ok","t":"Menus in 11 languages, including Spanish, Hindi and Portuguese. You can chat in any language; English works best."},"access":{"s":"ok","t":"Anthropic posts accessibility reports (VPATs) in its Trust Center; the newest covers WCAG 2.2 A and AA. Some documents may need an access request."}}'::jsonb, 'Pricing after the free year, Chromebook support, U.S.-only processing for district accounts, and which partner tools work on individual accounts aren''t confirmed.', array['https://claude.com/solutions/teachers', 'https://www.anthropic.com/news/claude-for-teachers', 'https://claude.com/blog/claude-for-teachers-now-available-for-schools-and-districts', 'https://support.claude.com/en/articles/15926041-claude-for-teachers-your-data-and-our-terms', 'https://www.anthropic.com/legal/k12-terms', 'https://www.anthropic.com/legal/k12-dpa', 'https://claude.com/download', 'https://privacy.claude.com/en/articles/7996890-where-are-your-servers-located-do-you-host-your-models-on-eu-servers']::text[], array['Student accounts', 'Single sign-on on individual teacher accounts']::text[])
on conflict (id) do update set name = excluded.name, company = excluded.company, category_id = excluded.category_id, ease = excluded.ease, verified = excluded.verified, subjects = excluded.subjects, description = excluded.description, uses = excluded.uses, personas = excluded.personas, free_status = excluded.free_status, pricing = excluded.pricing, privacy = excluded.privacy, connects = excluded.connects, equity = excluded.equity, review_note = excluded.review_note, urls = excluded.urls, not_offered = excluded.not_offered;

-- terms (46)
insert into public.terms (id, abbr, full_name, kind, definition) values
  ('ferpa', 'FERPA', 'Family Educational Rights and Privacy Act', 'privacy', 'The federal law that protects student education records. Schools can share records with a vendor only for a school purpose and under the school''s control, which is why districts sign agreements before staff use a tool with student information. To see where a tool keeps and sends data, check “Where your data goes” in its Scouting report.'),
  ('coppa', 'COPPA', 'Children''s Online Privacy Protection Act', 'privacy', 'A federal law about collecting personal information from children under 13 online. Most high schoolers are 13 or older, but it still matters for younger students and for tools whose terms set a minimum age.'),
  ('cipa', 'CIPA', 'Children''s Internet Protection Act', 'privacy', 'Requires schools that get E-rate funding to filter harmful content and have an internet safety policy. It affects which AI sites your network allows.'),
  ('dpa', 'DPA', 'Data Privacy Agreement', 'privacy', 'A signed contract between a district and a vendor that spells out what student data the tool can collect, how it is protected, and when it is deleted. No DPA usually means: no student information in that tool.'),
  ('sdpc', 'SDPC', 'Student Data Privacy Consortium', 'privacy', 'A national group of districts and states that shares standard DPAs. Many districts check the SDPC registry to see whether a vendor already signed an agreement in their state.'),
  ('pii', 'PII', 'Personally identifiable information', 'privacy', 'Anything that points to a specific student or family: names, ID numbers, birthdates, addresses, photos, or a detail so specific it gives away who it is. Remove it before you paste anything into AI.'),
  ('data-location', 'Data location', 'Where data is stored vs. where it''s processed', 'privacy', 'Stored is where a company keeps your data over time, like the file cabinet a student''s file sits in. Processed is anywhere your data is sent to be used, like the computers that write an AI tool''s answers, or a support team. A tool can store data in the U.S. but process it in other countries, where different privacy laws apply. Many district agreements require both to stay in the U.S., so check both in a tool''s Scouting report before using it with student information.'),
  ('aup', 'AI policy', 'District AI / acceptable use policy', 'privacy', 'Your district''s rules for which AI tools staff and students may use, and how. It usually names approved tools and says what data can go into them. When in doubt, ask your tech coordinator.'),
  ('iep', 'IEP', 'Individualized Education Program', 'school', 'A legal plan for a student who qualifies for special education. It lists goals, services and accommodations. AI can help draft wording, but the IEP team decides, and student details must stay out of non-approved tools.'),
  ('504', '504 plan', 'Section 504 accommodation plan', 'school', 'A plan that gives a student with a disability equal access through accommodations, like extra time or preferential seating, without specialized instruction.'),
  ('mtss', 'MTSS', 'Multi-Tiered System of Supports', 'school', 'A school-wide framework that sorts support into tiers: Tier 1 for everyone, Tier 2 for small groups, Tier 3 for intensive help. It covers academics and behavior.'),
  ('rti', 'RTI', 'Response to Intervention', 'school', 'The academic side of tiered support: screen students, give targeted help, and check progress often to see if it''s working.'),
  ('pbis', 'PBIS', 'Positive Behavioral Interventions and Supports', 'school', 'A framework for teaching and rewarding expected behavior instead of only reacting to problems. Behavior plans often use its language.'),
  ('plc', 'PLC', 'Professional Learning Community', 'school', 'A team of teachers, often by grade or subject, who meet regularly to look at student work and data and plan next steps together.'),
  ('lms', 'LMS', 'Learning Management System', 'school', 'Where classes live online: assignments, grades and materials. Google Classroom, Canvas and Schoology are common examples.'),
  ('sis', 'SIS', 'Student Information System', 'school', 'The official database for enrollment, attendance, schedules and report-card grades, such as PowerSchool or Infinite Campus. Treat anything from it as sensitive.'),
  ('udl', 'UDL', 'Universal Design for Learning', 'school', 'Planning lessons so every student can access them from the start: several ways to take in information, show learning and stay engaged.'),
  ('ml', 'ML / ELL', 'Multilingual learner / English language learner', 'school', 'A student who is learning English while learning content. AI translation and leveled texts can help, but have a fluent speaker check family-facing translations.'),
  ('differentiation', 'Differentiation', 'Adjusting instruction for different learners', 'school', 'Changing the content, process or product of a lesson so students at different levels can all reach the goal. AI is good at fast first drafts of leveled versions.'),
  ('scaffolding', 'Scaffolding', 'Temporary supports', 'school', 'Supports like sentence starters, graphic organizers or worked examples that help a student do a task now and are removed as they grow.'),
  ('formative', 'Formative assessment', 'Checks for understanding during learning', 'school', 'Low-stakes checks, like exit tickets or quick polls, that tell you what to reteach tomorrow. Not for the gradebook.'),
  ('summative', 'Summative assessment', 'End-of-unit measure', 'school', 'A test, project or essay that measures what students learned at the end of a unit or course.'),
  ('exit-ticket', 'Exit ticket', 'A 2–3 question check at the end of class', 'school', 'A quick formative check students answer before leaving. Sorting the answers tells you who''s ready to move on.'),
  ('rubric', 'Rubric', 'A scoring guide', 'school', 'A table that lists the criteria for a task and describes what each level of quality looks like, so grading is fair and students know the target.'),
  ('standards', 'Standards', 'State learning standards (e.g. CCSS, NGSS)', 'school', 'What students should know and be able to do in each grade and subject. Ask AI to align to your state''s standards by code, then double-check the codes.'),
  ('dok', 'DOK', 'Depth of Knowledge', 'school', 'A 1–4 scale of how complex a task''s thinking is, from recall (1) to extended reasoning (4). Useful for asking AI for harder or easier questions.'),
  ('lexile', 'Lexile', 'A reading-level measure', 'school', 'A number that estimates how hard a text is to read. AI leveling tools often target a Lexile or grade band; check the output, since AI estimates can be off.'),
  ('genai', 'Generative AI', 'AI that creates new text, images or audio', 'ai', 'Tools like ChatGPT, Gemini and Copilot that produce new content from your instructions, instead of just finding existing content.'),
  ('llm', 'LLM', 'Large language model', 'ai', 'The engine behind AI chat tools. It predicts likely next words from patterns in huge amounts of text. That makes it fluent, but not automatically correct.'),
  ('prompt', 'Prompt', 'What you type to the AI', 'ai', 'Your instructions. Good prompts name the role, the grade level, the goal, the format and any limits, just like a clear assignment sheet.'),
  ('system-prompt', 'System prompt', 'Standing instructions for every chat', 'ai', 'Instructions you set once, such as your subject, grade and tone, so you don''t repeat them. Called Gems in Gemini, custom GPTs or projects in ChatGPT, and agents in Copilot.'),
  ('hallucination', 'Hallucination', 'Confident but wrong output', 'ai', 'When AI makes up facts, quotes, citations or standards codes that sound real. Always check facts, sources and standards before anything reaches students or families.'),
  ('detector', 'AI detector', 'Tools that claim to spot AI writing', 'ai', 'AI-writing detectors are unreliable: they miss AI text and wrongly flag human writing, especially from multilingual learners. Don''t use a detector score alone as evidence of cheating.'),
  ('bias', 'Bias', 'Unfair patterns in AI output', 'ai', 'AI can repeat stereotypes from its training data, for example in example names, behavior descriptions or feedback tone. Read output with an equity lens before using it.'),
  ('grounding', 'Grounding', 'Answering only from sources you give it', 'ai', 'Asking the AI to use only your uploaded documents, like a handbook or curriculum guide. Tools such as NotebookLM are built for this, and it cuts down on made-up answers.'),
  ('training', 'Model training', 'Whether your data teaches the AI', 'privacy', 'Some consumer AI tools may use your chats to improve their models. Education and enterprise versions usually promise not to. Check the setting and the district agreement.'),
  ('sdg4', 'SDG 4', 'UN Sustainable Development Goal 4: Quality Education', 'school', 'One of 17 global goals the United Nations adopted in 2015: ensure inclusive and equitable quality education and promote lifelong learning opportunities for all. Its targets cover finishing school, job skills, equal access, literacy, safe schools and teacher training.'),
  ('equity', 'Equity', 'Giving each student what they need to succeed', 'school', 'Equality gives everyone the same thing; equity gives each person what they need to reach the same goal. For AI tools, it means asking who can''t use a tool because of cost, devices, internet, language or disability.'),
  ('wcag', 'WCAG', 'Web Content Accessibility Guidelines', 'school', 'The international standard for making websites and apps usable by people with disabilities. A 2024 federal rule (ADA Title II) requires US public schools'' web content to meet WCAG 2.1 Level AA, with deadlines starting in 2026.'),
  ('vpat', 'VPAT / ACR', 'Voluntary Product Accessibility Template / Accessibility Conformance Report', 'school', 'A vendor''s report on how well its product meets accessibility standards like WCAG. Ask for one before your district buys a tool.'),
  ('alt-text', 'Alt text', 'A written description of an image', 'school', 'Short text that a screen reader reads aloud in place of an image, so students who are blind or have low vision get the same information.'),
  ('rostering', 'Rostering', 'Loading class lists automatically', 'school', 'Copying class lists and student accounts from the SIS into a tool, so teachers don''t type them in. Most districts use a rostering service like Clever or ClassLink, which connects to SIS systems such as Infinite Campus, PowerSchool and Skyward.'),
  ('oneroster', 'OneRoster', 'A standard for sharing class rosters and grades', 'school', 'A common format (from the education tech group 1EdTech) that lets an SIS, an LMS and apps exchange class lists and grades without custom work.'),
  ('lti', 'LTI', 'Learning Tools Interoperability', 'school', 'A standard plug-in method that lets a tool open inside an LMS like Canvas or Schoology, often with the right class and student already selected.'),
  ('passback', 'Grade passback', 'Scores flow into your gradebook', 'school', 'When a tool sends student scores straight into an LMS or SIS gradebook, so teachers don''t re-enter them. Check what data goes along with the scores.'),
  ('human-loop', 'Human in the loop', 'A person reviews before it counts', 'ai', 'AI drafts; an educator decides. Grades, IEP language, discipline and family messages should always get a human read before they go anywhere.')
on conflict (id) do update set abbr = excluded.abbr, full_name = excluded.full_name, kind = excluded.kind, definition = excluded.definition;

-- plays (25)
insert into public.plays (id, no, title, roles, subjects, sdg, inclusion, touches_student_info, tools, prompt, tip) values
  ('lesson', 1, 'Standards-aligned lesson plan', array['teacher', 'coach']::text[], '{}'::text[], array['4.1']::text[], false, false, array['magicschool', 'gemini', 'chatgpt']::text[], 'Act as an experienced [grade] [subject] teacher in [state].
Write a [50]-minute lesson plan on [topic] aligned to [standard code, e.g. CCSS.ELA-LITERACY.RL.9-10.2].
Include: a learning target in student-friendly words, a 5-minute warm-up, direct instruction, a partner activity, a 3-question exit ticket, and one way to support multilingual learners and students with IEPs.
Format as a table with timings. Flag anything I should double-check, including the standard code.', 'AI often invents standards codes. Check the code against your state''s standards site.'),
  ('levels', 2, 'Same text, three reading levels', array['teacher', 'sped']::text[], array['ela', 'ss', 'sci']::text[], array['4.5', '4.6']::text[], true, false, array['diffit', 'magicschool', 'brisk']::text[], 'Rewrite the passage below at three reading levels: [grade 5], [grade 8] and [grade 10].
Keep every key fact and vocabulary word: [list words]. Bold the vocabulary words and add a short glossary under each version.
After each version, add 3 comprehension questions at DOK 1, 2 and 3.

Passage:
[paste text you have the right to use]', 'Keep the content the same so all students discuss the same ideas.'),
  ('rubric', 3, 'Rubric from an assignment sheet', array['teacher', 'sped', 'coach']::text[], '{}'::text[], array['4.1']::text[], false, false, array['magicschool', 'brisk', 'eduaide']::text[], 'Create a 4-level analytic rubric (Exceeds, Meets, Approaching, Beginning) for this assignment: [paste assignment].
Criteria: [e.g. claim, evidence, reasoning, conventions].
Write each cell as an observable behavior a student could self-check. Add a student-friendly ''I can'' checklist version underneath.', 'Share the checklist version with students before they start.'),
  ('exit', 4, 'Exit tickets that sort the room', array['teacher']::text[], array['math', 'sci']::text[], array['4.1', '4.6']::text[], false, false, array['magicschool', 'curipod', 'khanmigo']::text[], 'Write 3 exit-ticket questions for today''s lesson on [topic] for [grade] [subject].
Q1 checks the core skill. Q2 targets the most common misconception: [describe it, or ask AI to name it]. Q3 is a stretch question.
For each, list what a wrong answer tells me and a 5-minute reteach idea for tomorrow.', 'Sort answers into three piles: ready, almost, reteach.'),
  ('family-email', 5, 'Plain-language family email', array['teacher', 'counselor', 'office', 'admin']::text[], '{}'::text[], array['4.1', '4.5']::text[], false, true, array['gemini', 'copilot', 'magicschool']::text[], 'Rewrite this message to families in warm, plain language at about a 6th-grade reading level. Keep it under 150 words, lead with what families need to do and by when, and end with how to reach me.
Do not add facts that aren''t in my draft.

Draft (names and IDs removed):
[paste]', 'Write ''your student'' instead of a name, then add the name yourself in your email program.'),
  ('newsletter', 6, 'Translated family newsletter', array['office', 'admin', 'counselor']::text[], '{}'::text[], array['4.5']::text[], true, false, array['gemini', 'copilot', 'canva']::text[], 'Turn these notes into a one-page family newsletter for [school name] with short headings: Dates to know, What''s happening, How to help at home.
Then translate the finished newsletter into [Spanish] and [second language]. Keep dates, times and phone numbers exactly as written. Mark any phrase where the translation might be unclear.

Notes:
[paste]', 'Have a fluent staff member or district translator review before sending. AI translation can miss tone and local terms.'),
  ('iep-goals', 7, 'IEP goal draft from anonymized notes', array['sped']::text[], '{}'::text[], array['4.5']::text[], true, true, array['magicschool', 'eduaide']::text[], 'I''m a special education teacher drafting IEP goals. Using the anonymized present-levels notes below, draft 2 measurable annual goals in SMART format (condition, behavior, criterion, timeframe) and 2–3 short-term objectives for each.
Area: [reading fluency / math calculation / self-regulation].
Use ''Student'' instead of any name.

Present levels (no names, IDs, birthdates or diagnoses):
[paste]', 'This is a first draft for the IEP team, not a decision. Only use a district-approved tool, and never paste the full IEP.'),
  ('behavior', 8, 'Positive behavior plan language', array['sped', 'counselor', 'teacher']::text[], '{}'::text[], array['4.5', '4.a']::text[], false, true, array['magicschool', 'gemini']::text[], 'Help me write strengths-based behavior support language (PBIS style) for a [grade] student.
Target behavior: [describe in observable terms]. Likely function: [attention / escape / sensory / tangible]. What helps: [list].
Draft: a replacement behavior, 3 prevention strategies, how adults will respond, and a simple student check-in card. Avoid labels and judgmental words.
No names or identifying details are included.', 'Read for bias: would this wording feel fair if it were about your own child?'),
  ('duty', 9, 'Duty schedule & bus announcement', array['admin', 'office']::text[], '{}'::text[], array['4.a']::text[], false, false, array['copilot', 'gemini']::text[], 'Here is next week''s duty roster and bus changes. Write:
1) a 30-second morning announcement for students,
2) a short staff email with a table of who is on which duty and when,
3) a 2-sentence text-message version for families about the bus change.
Keep times and route numbers exactly as given.

Roster and changes:
[paste staff names and duties]', 'Staff names are fine here; student names are not.'),
  ('agenda', 10, 'Staff meeting agenda that ends on time', array['admin', 'coach']::text[], '{}'::text[], array['4.c']::text[], false, false, array['copilot', 'gemini', 'notebooklm']::text[], 'Build a [45]-minute staff meeting agenda from these topics: [list].
Put decisions first and announcements in a ''read before'' section instead of meeting time. For each item give: owner, minutes, and the decision or outcome we need.
Add a 5-minute celebration opener and a closing ''who does what by when'' table.', 'Send the ''read before'' section the day before the meeting.'),
  ('grant', 11, 'Grant summary for the school board', array['admin', 'coach']::text[], '{}'::text[], array['4.c']::text[], false, false, array['notebooklm', 'chatgpt', 'copilot']::text[], 'Summarize the attached grant [name] for a school-board update. Include: purpose, amount and timeline, who is eligible, what we must report, matching requirements, and the 3 biggest risks or deadlines.
Use only the attached documents. If something isn''t in them, say ''not stated''.
Then draft a 150-word plain-language summary for our website.', 'Grounding the AI in the grant document keeps it from inventing requirements.'),
  ('college', 12, 'Grade-by-grade college & career checklist', array['counselor']::text[], '{}'::text[], array['4.3']::text[], false, false, array['gemini', 'chatgpt', 'canva']::text[], 'Create a 9th–12th grade college and career planning checklist for [state] public high school students and families. Include deadlines by month for 11th and 12th grade, FAFSA timing, testing options, CTE and apprenticeship paths, and a column for ''who can help at school''.
Keep it to one page and write at an 8th-grade reading level. Mark any dates I should verify.', 'Deadlines change every year. Verify FAFSA and college dates on the official sites.'),
  ('pd', 13, '60-minute PD on AI basics', array['coach', 'admin']::text[], '{}'::text[], array['4.c']::text[], false, false, array['notebooklm', 'magicschool', 'curipod']::text[], 'Design a 60-minute professional development session for high school teachers new to AI. Goals: understand what AI is good and bad at, try one planning task, and know our district rules.
Include a hands-on activity using [approved tool], a 5-minute segment on student privacy and FERPA, a discussion on AI detectors'' limits, and an exit survey.
Base district rules only on this policy: [paste policy].', 'Teachers learn fastest by doing one real task from their own week.'),
  ('dbq', 14, 'Primary-source analysis scaffold', array['teacher']::text[], array['ss']::text[], array['4.6']::text[], false, false, array['brisk', 'magicschool', 'khanmigo']::text[], 'Create a scaffolded analysis sheet for this primary source: [title, date, paste text].
Include sourcing questions (who, when, why, audience), close-reading questions with line numbers, a contextualization prompt, and a claim-evidence-reasoning paragraph frame. Add sentence starters for multilingual learners.', 'Check historical context claims against your textbook or a trusted source.'),
  ('math-ex', 15, 'Worked examples & misconceptions', array['teacher', 'sped']::text[], array['math']::text[], array['4.6']::text[], false, false, array['khanmigo', 'magicschool', 'chatgpt']::text[], 'For [skill, e.g. solving two-step linear equations], write:
- 2 fully worked examples with each step explained in plain words,
- 1 example with a common mistake for students to find and fix,
- 4 practice problems getting harder, with an answer key.
Show every arithmetic step so I can check the math.', 'AI makes arithmetic slips. Work the answer key yourself before handing it out.'),
  ('lab', 16, 'Lab procedure to student-friendly steps', array['teacher', 'sped']::text[], array['sci', 'cte']::text[], array['4.5', '4.a']::text[], false, false, array['magicschool', 'diffit', 'canva']::text[], 'Rewrite this lab procedure as numbered student steps with one action per step, a materials checklist, and safety callouts in bold before the step they apply to. Then make a picture-supported version for students who need it, describing which icon goes with each step.

Procedure:
[paste]', 'Keep your school''s official safety rules in charge; AI wording supports them, it doesn''t replace them.'),
  ('wl-story', 17, 'Comprehensible-input story', array['teacher']::text[], array['wl']::text[], array['4.7']::text[], false, false, array['chatgpt', 'gemini', 'curipod']::text[], 'Write a 200-word story in [Spanish] for [Spanish 2] students using mostly high-frequency words and these target structures: [list]. Repeat each structure at least 4 times.
After the story, add 5 yes/no and 3 either/or questions in the target language, and a vocabulary list with English meanings.', 'Read it aloud first; fix anything that sounds unnatural to you.'),
  ('ela-disc', 18, 'Discussion questions for a novel', array['teacher']::text[], array['ela']::text[], array['4.6']::text[], false, false, array['brisk', 'magicschool', 'curipod']::text[], 'Create Socratic seminar questions for chapters [x–y] of [book]. Include 3 opening questions, 4 core questions tied to [theme], and 2 closing questions connecting to students'' lives. Add text-evidence page prompts and a peer-feedback tracker.', 'Check quotes and page numbers against your edition; AI may misquote.'),
  ('cte-scn', 19, 'Real-world industry scenario', array['teacher', 'counselor']::text[], array['cte']::text[], array['4.4']::text[], false, false, array['chatgpt', 'gemini', 'magicschool']::text[], 'Write a realistic workplace scenario for a [course, e.g. Health Science / Culinary / IT] class where students must [skill]. Include a client or manager request, constraints (budget, time, safety), the deliverable, and a grading checklist tied to [industry certification or standard].', 'Ask a local industry partner to sanity-check the scenario.'),
  ('absence', 20, 'Attendance & absence letter set', array['office', 'counselor', 'admin']::text[], '{}'::text[], array['4.1']::text[], false, true, array['gemini', 'copilot']::text[], 'Write three versions of an attendance letter to families: (1) friendly first notice, (2) concerned second notice with an invitation to meet, (3) formal notice that follows [state] attendance law as described here: [paste district language].
Tone: supportive, never shaming. Use [Student Name] and [Date] as placeholders.', 'Fill in the placeholders in your SIS or mail-merge, not in the AI tool.'),
  ('bias-check', 21, 'Cultural bias check on a lesson', array['teacher', 'coach']::text[], '{}'::text[], array['4.5', '4.7']::text[], true, false, array['magicschool', 'gemini', 'copilot']::text[], 'Review the lesson materials below with an equity lens for a diverse public high school.
Check for: stereotypes, examples that assume one culture, family structure, income level or religion, names and images that represent only some groups, idioms that confuse multilingual learners, and topics that could be harmful to students with lived experience.
For each issue, quote the line, explain why it matters, and suggest a replacement. Then list 3 ways to include perspectives that are missing.

Materials:
[paste]', 'AI has its own blind spots. Ask a colleague, and your students, too.'),
  ('accessible', 22, 'Make materials work for every sense', array['sped', 'teacher', 'coach']::text[], '{}'::text[], array['4.5', '4.a']::text[], true, false, array['magicschool', 'copilot', 'gemini']::text[], 'Make the handout below accessible for a student who is blind or has low vision and a student who is Deaf or hard of hearing.
1) Rewrite it with clear headings, short paragraphs and lists so a screen reader reads it in a logical order.
2) Write alt text for each image or diagram I describe: [describe images].
3) For the video [title/link], list what captions and a transcript must include, and draft a short audio description of key visuals.
4) Suggest a hands-on or tactile alternative for any visual-only activity.

Handout:
[paste]', 'Check your work with the screen reader built into your device, and ask your vision or hearing specialist.'),
  ('low-literacy', 23, 'Family message anyone can read', array['office', 'counselor', 'teacher']::text[], '{}'::text[], array['4.5']::text[], true, false, array['gemini', 'copilot', 'canva']::text[], 'Rewrite this school message for families who may have limited reading skills or are new to US schools.
Use short sentences, common words and a 3rd–4th grade reading level. Put the one action families must take first, in bold. Explain any school words (like ''conference'' or ''IEP'') in plain language. Suggest 2–3 simple icons that could go next to key points.
Also write a 30-second phone or voicemail script with the same information.

Message:
[paste]', 'A voice message or a phone call often reaches more families than a letter.'),
  ('unplugged', 24, 'Device-free version of a lesson', array['teacher']::text[], '{}'::text[], array['4.5', '4.1']::text[], true, false, array['magicschool', 'chatgpt', 'eduaide']::text[], 'Here is a lesson that depends on student devices and internet: [paste or describe].
Create a version that works with no devices, for days when Wi-Fi is down or for students without a device or internet at home. Keep the same learning target. Use paper, cards, group roles, movement or a whiteboard. List what to print or prepare, and how to give students who missed the online version the same chance at full credit.', 'Plan this before you need it. Families without home internet will thank you.'),
  ('newcomer', 25, 'Newcomer welcome pack', array['counselor', 'office', 'teacher']::text[], '{}'::text[], array['4.5']::text[], true, false, array['gemini', 'copilot', 'canva']::text[], 'Create a welcome pack for a newly arrived multilingual student and family joining [school name] in grade [9–12]. Their home language is [language].
Include: a one-page ''first week'' guide (bell schedule basics, lunch, where to get help), 15 survival phrases in English with translations, a map checklist of key places, who to contact at school, and a short note from the counselor.
Keep times and room numbers exactly as I give them: [paste details]. Mark any translation a fluent speaker should check.', 'Pair the student with a peer buddy who speaks their language, if you can.')
on conflict (id) do update set no = excluded.no, title = excluded.title, roles = excluded.roles, subjects = excluded.subjects, sdg = excluded.sdg, inclusion = excluded.inclusion, touches_student_info = excluded.touches_student_info, tools = excluded.tools, prompt = excluded.prompt, tip = excluded.tip;

-- system_prompts (6)
insert into public.system_prompts (id, title, roles, where_key, where_text, prompt, example, try_it) values
  ('sys-teacher', 'Teacher planning partner', array['teacher']::text[], 'gemini', 'Gemini: open Gems → New Gem and paste into Instructions. (Google says Gems end for school accounts on or after June 1, 2027.)', 'You are my planning partner. I teach [grade] [subject] at a public high school in [state]. My classes include multilingual learners and students with IEPs and 504 plans.
When I ask for materials:
- Align to [state] standards and show the standard code, flagged for me to verify.
- Offer a supported version and a stretch version.
- Keep student-facing text at grade level unless I ask otherwise.
- Use tables for plans and keep explanations short.
- Never ask for or use student names or identifying details. If I paste any, remind me to remove them.
- Say when you''re unsure instead of guessing.', 'Example fill-in: 10th grade Biology in Ohio; two sections of co-taught classes.', 'Plan Monday''s lesson on cell transport with a lab-free option.'),
  ('sys-sped', 'Special ed co-planner', array['sped']::text[], 'magicschool', 'MagicSchool: paste at the top of a Raina chat, or save it as a custom tool if your plan allows.', 'You support a high school special education team. Help me adapt materials, draft measurable goal language, and suggest accommodations and scaffolds.
Rules:
- Refer to students only as ''Student'' or ''Student A''. Never request names, IDs, diagnoses or birthdates.
- Write goals in condition / behavior / criterion / timeframe format.
- Use strengths-based, person-first language.
- Remind me that the IEP team makes all decisions and that drafts need team review.
- Follow our district AI policy: [paste the relevant rule].', null, 'Turn this worksheet into a version with chunked steps and sentence starters.'),
  ('sys-counselor', 'Counselor communications helper', array['counselor']::text[], 'gemini', 'Gemini: open Gems → New Gem and paste into Instructions. (Google says Gems end for school accounts on or after June 1, 2027.)', 'You help a high school counselor write clear, warm messages and planning resources for students and families.
- Write at about an 8th-grade reading level; offer a Spanish version on request.
- Be encouraging and non-judgmental; never diagnose or give medical or legal advice.
- For anything about safety, self-harm or abuse, tell me to follow our school''s crisis protocol instead of drafting a response.
- Don''t ask for or keep student names or personal details.', null, 'Draft a reminder to seniors about the scholarship workshop on Thursday.'),
  ('sys-admin', 'Principal''s chief of staff', array['admin']::text[], 'copilot', 'Copilot: create an agent (or a notebook) and paste into its instructions.', 'You are the chief of staff for a public high school principal. Help me with staff communications, meeting agendas, schedules, board summaries and grant reporting.
- Lead with the decision or action needed.
- Keep staff emails under 200 words with bullets for dates and owners.
- When summarizing documents, use only what''s in them and say ''not stated'' for gaps.
- Match a calm, positive, professional school voice.
- Never include student names or personnel matters in drafts.', null, 'Turn these notes into Friday''s staff update with a ''needs your action'' section.'),
  ('sys-office', 'Front desk helper', array['office']::text[], 'copilot', 'Copilot: create an agent (or a notebook) and paste into its instructions.', 'You help the front office of [school name] write notices, phone scripts, sign-in instructions and family messages.
- Use short sentences and a friendly, welcoming tone.
- Keep dates, times, room numbers and phone numbers exactly as I give them.
- When I ask for a translation, keep formatting and mark unclear phrases for review.
- Never include student names, ID numbers, health or custody information.', null, 'Write a sign for the front door about the new visitor check-in process.'),
  ('sys-coach', 'AI rollout coach', array['coach', 'admin']::text[], 'notebooklm', 'NotebookLM: upload your policy docs to a notebook, then paste this into the chat''s custom instructions.', 'You help an instructional coach plan teacher PD and AI tool rollouts. Use only the documents I upload (our district AI policy, approved-tool list and curriculum guides).
- When asked if a tool or use is allowed, quote the policy section or say it isn''t covered.
- Design PD that is hands-on and under 60 minutes.
- Include a privacy check (FERPA, DPA status) in every rollout plan.', null, 'Is it okay for teachers to use AI to give feedback on student essays? Cite the policy.')
on conflict (id) do update set title = excluded.title, roles = excluded.roles, where_key = excluded.where_key, where_text = excluded.where_text, prompt = excluded.prompt, example = excluded.example, try_it = excluded.try_it;

